G=load(); print(sorted(G))
inp,out=G['Demo pair 2 input'],G['Demo pair 2 output']
H,W=len(inp),len(inp[0])
# demo2: diagonal lines d=j-i
offs={}
for i in range(H):
    for j in range(W):
        if inp[i][j]: offs.setdefault(inp[i][j]-j if False else j-i,set()).add(inp[i][j])
print({o:sorted(c) for o,c in sorted(offs.items())})
p=len(offs)
P={}
for o,cs in offs.items():
    assert len(cs)==1; P[o%p]=cs.pop()
print('p',p,'P',P)
pred=[[P[(j-i)%p] for j in range(W)] for i in range(H)]
print('demo2 match:', pred==out)
# demo1: horizontal
i1,o1=G['Demo pair 1 input'],G['Demo pair 1 output']
rows=sorted({i for i in range(26) if i1[i][0]!=0})
p1=len(rows); P1={r%p1:i1[r][0] for r in rows}
pred1=[[P1[i%p1] for _ in range(26)] for i in range(26)]
print('demo1 match:', pred1==o1, p1, P1)

